-- A database at PRAGMA user_version 8 (move-in-dark plan session 3): a project "Old flags" whose stack
-- "Main" holds a lit cue, a cue flagging one position row move-in-dark, a cue flagging two, and a cue
-- whose position row is not flagged, beside a loose cue flagging one. Its schema is a v8 desk's after
-- move-in-dark session 1 (the stack's move_in_dark columns; cues has no move_in_dark_mode yet, which
-- the reconciliation adds before step 9 runs). Built from pre-fx-siblings.sql's schema with these
-- rows. Frozen: never regenerate it from a later commit. The desk's accounts and sessions are left out.


CREATE TABLE busk_banks (id INTEGER PRIMARY KEY AUTOINCREMENT, column_id INT NOT NULL, sort_order INT NOT NULL, "name" VARCHAR(255) NOT NULL, solo BOOLEAN DEFAULT 0 NOT NULL, flow VARCHAR(16) DEFAULT 'WRAP' NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_banks_column_id__id FOREIGN KEY (column_id) REFERENCES busk_columns(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_banks_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_banks_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_columns (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id INT NOT NULL, "row" INT NOT NULL, sort_order INT NOT NULL, width INT NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_columns_page_id__id FOREIGN KEY (page_id) REFERENCES busk_pages(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_columns_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_row CHECK ("row" BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_width CHECK (width BETWEEN -2147483648 AND 2147483647));
